-- Sample for local development and demos, cut from a full load (scripts/market/load.ts):
-- seven atlas crops in Viet Nam, the United States and India, annual producer prices since 2015.
-- Values are FAOSTAT's (Producer Prices, release 2026-10-09), unchanged. For the whole dataset run
-- `npm run db:load` against the local stack (docs/DATABASE.md).
-- item_crop_count in the views counts the crops of this sample only.

insert into public.data_sources
